    $c.util.getComponent('ipt_sumLgShr').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_lgshrhdCmstkShrs').getValue()) + scwin.rmComma($c.util.getComponent('ipt_lgshrhdPrefstkShrs').getValue())));

    // 최대주주 관계자 합계주식수
    $c.util.getComponent('ipt_sumRelShr').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_lgshrhdRelprnCmstkShrs').getValue()) + scwin.rmComma($c.util.getComponent('ipt_lgshrhdRelprnPrefstkShrs').getValue())));

    // 최대주주 보통주 소계  주식수
    $c.util.getComponent('ipt_sumSubCmn').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_lgshrhdCmstkShrs').getValue()) + scwin.rmComma($c.util.getComponent('ipt_lgshrhdRelprnCmstkShrs').getValue())));

    // 최대주주 우선주 소계 주식수
    $c.util.getComponent('ipt_sumSubPref').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_lgshrhdPrefstkShrs').getValue()) + scwin.rmComma($c.util.getComponent('ipt_lgshrhdRelprnPrefstkShrs').getValue())));

    // 최대주주 보통+우선주 소계 주식수
    $c.util.getComponent('ipt_sumSubTot').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_sumLgShr').getValue()) + scwin.rmComma($c.util.getComponent('ipt_sumRelShr').getValue())));

    fn_TotalChange();

    /* sdd-asis-lifecycle:end */
};


